#include <stdio.h>
#include <stdbool.h>
#include <string.h>

int L, C, P;
int board[8][8]; // 1: preta, 0: vazia
bool is_candidate[8][8];

int id[8][8];
int num_candidates;

int head[40], to[200], nxt[200], edge_cnt;
int match[40];
bool vis[40];

void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

bool dfs(int u) {
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int v = to[e];
        if (!vis[v]) {
            vis[v] = true;
            if (match[v] < 0 || dfs(match[v])) {
                match[v] = u;
                return true;
            }
        }
    }
    return false;
}

int main() {
    if (scanf("%d %d", &L, &C) != 2) return 0;
    if (scanf("%d", &P) != 1) return 0;

    for (int i = 0; i < P; i++) {
        int r, c;
        scanf("%d %d", &r, &c);
        board[r][c] = 1; // peça preta
    }

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    // Identificar casas candidatas (vazias com pelo menos uma vizinha preta)
    num_candidates = 0;
    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (board[r][c] == 0) {
                bool has_black_neighbor = false;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 1 && nr <= L && nc >= 1 && nc <= C) {
                        if (board[nr][nc] == 1) {
                            has_black_neighbor = true;
                            break;
                        }
                    }
                }
                if (has_black_neighbor) {
                    is_candidate[r][c] = true;
                    id[r][c] = num_candidates++;
                }
            }
        }
    }

    memset(head, -1, sizeof(head));
    edge_cnt = 0;

    // Construir o grafo bipartido entre casas candidatas
    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (is_candidate[r][c] && (r + c) % 2 == 0) {
                int u = id[r][c];
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 1 && nr <= L && nc >= 1 && nc <= C) {
                        if (is_candidate[nr][nc]) {
                            int v = id[nr][nc];
                            add_edge(u, v);
                        }
                    }
                }
            }
        }
    }

    // Emparelhamento máximo bipartido (algoritmo de Kuhn)
    memset(match, -1, sizeof(match));
    int max_matching = 0;
    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (is_candidate[r][c] && (r + c) % 2 == 0) {
                int u = id[r][c];
                memset(vis, false, sizeof(vis));
                if (dfs(u)) {
                    max_matching++;
                }
            }
        }
    }

    // Conjunto independente máximo em grafo bipartido = |V| - Matching Máximo
    int ans = num_candidates - max_matching;
    printf("%d\n", ans);

    return 0;
}
